{
  "units": [
    {
      "section": "scope_limitations",
      "slot": "scope",
      "text": "Aspose.Slides FOSS for Java provides read and write access to PPTX, PPSX, and POTX files, supporting Java 21 and later, with the package name org.aspose:aspose-slides-foss at version 26.8.0.",
      "fact_ids": [
        "identity:ecosystem",
        "identity:family",
        "identity:platform",
        "identity:repository",
        "identity:revision",
        "package:java_release",
        "package:name",
        "package:published_version",
        "package:version"
      ]
    },
    {
      "section": "scope_limitations",
      "slot": "limitation:1",
      "text": "The library is licensed under the MIT license, as stated in the LICENSE file.",
      "fact_ids": [
        "license:file",
        "license:spdx"
      ]
    },
    {
      "section": "scope_limitations",
      "slot": "limitation:2",
      "text": "Charts are not in the public API, as there is no ISlideCollection.addChart method available.",
      "fact_ids": [
        "license:file",
        "license:spdx"
      ]
    },
    {
      "section": "scope_limitations",
      "slot": "limitation:3",
      "text": "SmartArt, OLE objects, video, and audio are not modelled in the API.",
      "fact_ids": [
        "license:file",
        "license:spdx"
      ]
    },
    {
      "section": "scope_limitations",
      "slot": "limitation:4",
      "text": "Animations and slide transitions are not supported, as there is no ISlide.getTimeline or ISlide.getSlideShowTransition method.",
      "fact_ids": [
        "license:file",
        "license:spdx"
      ]
    },
    {
      "section": "scope_limitations",
      "slot": "limitation:5",
      "text": "Group shapes are not supported, as there is no IShapeCollection.addGroupShape method and no shape can hold child shapes.",
      "fact_ids": [
        "license:file",
        "license:spdx"
      ]
    },
    {
      "section": "scope_limitations",
      "slot": "limitation:6",
      "text": "Hyperlinks, sections, slide backgrounds, themes, slide size, rendering, conversion, VBA macros, digital signatures, and encryption are not modelled.",
      "fact_ids": [
        "license:file",
        "license:spdx"
      ]
    },
    {
      "section": "scope_limitations",
      "slot": "limitation:7",
      "text": "A known defect occurs when cloning a master: getMasters().addClone(...) returns a collection that reports a size of 2, but the saved package contains only one slide master, and the clone never reaches the file.",
      "fact_ids": [
        "inherited_unit:088.list"
      ]
    }
  ],
  "omitted": []
}
